"use client";
import{useCallback,useEffect,useState}from"react";import{AppShell}from"../ui/app-shell";import{usePlayerData}from"../../lib/use-player-data";import{getSupabaseBrowserClient}from"../../lib/supabase/client";import"../pilot.css";
type Player={id:string;display_name:string|null;email:string};type Enrolment={id:string;player_id:string;coach_id:string;status:string;start_date:string|null;target_end_date:string|null;pilot_goal:string;consent_confirmed_at:string|null;coach_summary:string};type Feedback={id:string;respondent_role:string;checkpoint:string;ease_score:number|null;confidence_score:number|null;reliability_score:number|null;what_worked:string;what_was_unclear:string;improvement_request:string;created_at:string};type Issue={id:string;category:string;severity:string;summary:string;detail:string;status:string;coach_notes:string;created_at:string};type Readiness={feedback_count:number;average_ease:number|null;average_confidence:number|null;average_reliability:number|null;open_issues:number;blockers:number;resolved_issues:number;ready_to_complete:boolean};
const emptyScores={checkpoint:"week_2",ease_score:4,confidence_score:4,reliability_score:4,what_worked:"",what_was_unclear:"",improvement_request:"",follow_up_allowed:true};
export default function PilotPage(){const{profile}=usePlayerData();const coach=profile?.role==="coach"||profile?.role==="admin";const[players,setPlayers]=useState<Player[]>([]),[target,setTarget]=useState(""),[enrolment,setEnrolment]=useState<Enrolment|null>(null),[feedback,setFeedback]=useState<Feedback[]>([]),[issues,setIssues]=useState<Issue[]>([]),[readiness,setReadiness]=useState<Readiness|null>(null),[form,setForm]=useState(emptyScores),[issue,setIssue]=useState({category:"usability",severity:"medium",summary:"",detail:""}),[message,setMessage]=useState(""),[busy,setBusy]=useState(false);
 const loadPlayers=useCallback(async()=>{const sb=getSupabaseBrowserClient();if(!sb||!profile)return;if(!coach){setPlayers([{id:profile.id,display_name:profile.display_name,email:profile.email}]);setTarget(profile.id);return}const{data:links}=await sb.from("coach_player_links").select("player_id").eq("coach_id",profile.id);const ids=(links||[]).map(x=>x.player_id);if(!ids.length){setPlayers([]);return}const{data}=await sb.from("profiles").select("id,display_name,email").in("id",ids).order("display_name");setPlayers((data||[])as Player[]);setTarget(current=>current||data?.[0]?.id||"")},[profile,coach]);
 const loadPilot=useCallback(async()=>{const sb=getSupabaseBrowserClient();if(!sb||!profile||!target)return;let query=sb.from("pilot_enrolments").select("*").eq("player_id",target);if(coach)query=query.eq("coach_id",profile.id);const{data}=await query.maybeSingle();const current=data as Enrolment|null;setEnrolment(current);if(!current){setFeedback([]);setIssues([]);setReadiness(null);return}const[{data:f},{data:i},{data:r}]=await Promise.all([sb.from("pilot_feedback").select("*").eq("enrolment_id",current.id).order("created_at",{ascending:false}),sb.from("pilot_issues").select("*").eq("enrolment_id",current.id).order("created_at",{ascending:false}),sb.rpc("pilot_readiness",{target_enrolment:current.id})]);setFeedback((f||[])as Feedback[]);setIssues((i||[])as Issue[]);setReadiness(r as Readiness)},[profile,target,coach]);useEffect(()=>{const timer=setTimeout(()=>void loadPlayers(),0);return()=>clearTimeout(timer)},[loadPlayers]);useEffect(()=>{const timer=setTimeout(()=>void loadPilot(),0);return()=>clearTimeout(timer)},[loadPilot]);
 const enrol=async()=>{const sb=getSupabaseBrowserClient();if(!sb||!profile||!target)return;setBusy(true);const today=new Date(),end=new Date(today);end.setDate(end.getDate()+56);const{error}=await sb.from("pilot_enrolments").upsert({player_id:target,coach_id:profile.id,status:"active",start_date:today.toISOString().slice(0,10),target_end_date:end.toISOString().slice(0,10),pilot_goal:"Validate the complete Vector player journey with real use.",consent_confirmed_at:new Date().toISOString()},{onConflict:"player_id,coach_id"});setBusy(false);setMessage(error?error.message:"Player enrolled in the selected pilot.");if(!error)await loadPilot()};
 const saveFeedback=async()=>{const sb=getSupabaseBrowserClient();if(!sb||!profile||!enrolment)return;setBusy(true);const{error}=await sb.from("pilot_feedback").upsert({...form,enrolment_id:enrolment.id,respondent_id:profile.id,respondent_role:coach?"coach":"player",updated_at:new Date().toISOString()},{onConflict:"enrolment_id,respondent_id,checkpoint"});setBusy(false);setMessage(error?error.message:"Pilot feedback saved.");if(!error){setForm(emptyScores);await loadPilot()}};
 const reportIssue=async()=>{const sb=getSupabaseBrowserClient();if(!sb||!profile||!enrolment||!issue.summary.trim())return;setBusy(true);const{error}=await sb.from("pilot_issues").insert({...issue,enrolment_id:enrolment.id,reported_by:profile.id});setBusy(false);setMessage(error?error.message:"Issue added to the pilot log.");if(!error){setIssue({category:"usability",severity:"medium",summary:"",detail:""});await loadPilot()}};
 const updateIssue=async(id:string,status:string)=>{const sb=getSupabaseBrowserClient();if(!sb)return;await sb.from("pilot_issues").update({status,resolved_at:status==="resolved"?new Date().toISOString():null,updated_at:new Date().toISOString()}).eq("id",id);await loadPilot()};const complete=async()=>{const sb=getSupabaseBrowserClient();if(!sb||!enrolment)return;const{error}=await sb.from("pilot_enrolments").update({status:"completed",updated_at:new Date().toISOString()}).eq("id",enrolment.id);setMessage(error?error.message:"Pilot completed and retained for review.");if(!error)await loadPilot()};
 return <AppShell active="pilot"><header className="page-heading"><div><p className="eyebrow">Package 7H.3 · Selected-player pilot</p><h1>Test with purpose. Improve from evidence.</h1><p>Run a controlled player pilot, collect feedback at agreed checkpoints and resolve issues before wider release.</p></div></header>{message&&<div className="success-banner" role="status">{message}</div>}{coach&&<section className="pilot-select"><label>Selected linked player<select value={target} onChange={e=>setTarget(e.target.value)}><option value="">Select player</option>{players.map(p=><option key={p.id} value={p.id}>{p.display_name||p.email}</option>)}</select></label>{target&&!enrolment&&<button className="primary-action" disabled={busy} onClick={enrol}>Enrol in pilot</button>}</section>}{!enrolment&&<section className="pilot-empty"><h2>{coach?"Select and enrol a linked player":"No active pilot yet"}</h2><p>{coach?"Pilot access is deliberate and separate from ordinary player access.":"Your coach will invite you when your pilot is ready."}</p></section>}{enrolment&&<><section className="pilot-status"><div><span className={`pilot-pill ${enrolment.status}`}>{enrolment.status}</span><h2>{players.find(p=>p.id===target)?.display_name||"Pilot player"}</h2><p>{enrolment.pilot_goal}</p></div><dl><div><dt>Started</dt><dd>{enrolment.start_date||"Not set"}</dd></div><div><dt>Target end</dt><dd>{enrolment.target_end_date||"Not set"}</dd></div></dl></section><section className="pilot-metrics"><article><strong>{readiness?.feedback_count||0}</strong><span>feedback checkpoints</span></article><article><strong>{readiness?.average_ease??"—"}</strong><span>ease / 5</span></article><article><strong>{readiness?.average_confidence??"—"}</strong><span>confidence / 5</span></article><article><strong>{readiness?.open_issues||0}</strong><span>open issues</span></article><article className={readiness?.blockers?"alert":""}><strong>{readiness?.blockers||0}</strong><span>blockers</span></article></section><div className="pilot-grid"><section className="pilot-panel"><p className="eyebrow">Checkpoint feedback</p><h2>Tell us about real use</h2><label>Checkpoint<select value={form.checkpoint} onChange={e=>setForm({...form,checkpoint:e.target.value})}>{["onboarding","week_2","week_4","week_8","final","ad_hoc"].map(x=><option key={x} value={x}>{x.replace("_"," ")}</option>)}</select></label><div className="score-row">{[["Ease", "ease_score"],["Confidence", "confidence_score"],["Reliability", "reliability_score"]].map(([label,key])=><label key={key}>{label}<select value={String(form[key as keyof typeof form])} onChange={e=>setForm({...form,[key]:Number(e.target.value)})}>{[1,2,3,4,5].map(n=><option key={n}>{n}</option>)}</select></label>)}</div><label>What worked<textarea value={form.what_worked} onChange={e=>setForm({...form,what_worked:e.target.value})}/></label><label>What was unclear<textarea value={form.what_was_unclear} onChange={e=>setForm({...form,what_was_unclear:e.target.value})}/></label><label>Most useful improvement<textarea value={form.improvement_request} onChange={e=>setForm({...form,improvement_request:e.target.value})}/></label><button className="primary-action" disabled={busy} onClick={saveFeedback}>Save checkpoint</button></section><section className="pilot-panel"><p className="eyebrow">Issue log</p><h2>Record a specific problem</h2><div className="score-row"><label>Category<select value={issue.category} onChange={e=>setIssue({...issue,category:e.target.value})}>{["usability","data","sync","content","access","other"].map(x=><option key={x}>{x}</option>)}</select></label><label>Severity<select value={issue.severity} onChange={e=>setIssue({...issue,severity:e.target.value})}>{["low","medium","high","blocker"].map(x=><option key={x}>{x}</option>)}</select></label></div><label>Short summary<input value={issue.summary} onChange={e=>setIssue({...issue,summary:e.target.value})}/></label><label>What happened<textarea value={issue.detail} onChange={e=>setIssue({...issue,detail:e.target.value})}/></label><button className="primary-action" disabled={busy||!issue.summary.trim()} onClick={reportIssue}>Add issue</button></section></div><section className="pilot-history"><div className="section-heading"><div><p className="eyebrow">Pilot evidence</p><h2>Feedback and issues</h2></div>{coach&&<button className="primary-action" disabled={!readiness?.ready_to_complete||enrolment.status==="completed"} onClick={complete}>Complete pilot</button>}</div>{issues.map(i=><article key={i.id}><div><span className={`severity ${i.severity}`}>{i.severity}</span><strong>{i.summary}</strong><small>{i.category} · {i.status}</small></div><p>{i.detail}</p>{coach&&i.status!=="resolved"&&<div><button onClick={()=>updateIssue(i.id,"in_review")}>Review</button><button onClick={()=>updateIssue(i.id,"resolved")}>Resolve</button></div>}</article>)}{feedback.map(f=><article key={f.id}><div><span className="feedback-tag">{f.checkpoint.replace("_"," ")}</span><strong>{f.respondent_role} feedback</strong><small>Ease {f.ease_score??"—"} · Confidence {f.confidence_score??"—"} · Reliability {f.reliability_score??"—"}</small></div><p>{f.what_worked||f.what_was_unclear||f.improvement_request||"Scores recorded."}</p></article>)}{!issues.length&&!feedback.length&&<p className="empty-copy">No pilot evidence recorded yet.</p>}</section></>}</AppShell>}
